from review import card,save,DATE

def b(title,text,citation=None):
 d=dict(title=title,text=text)
 if citation:d['citation']=citation
 return d

i='TCS-2889';_,c=card(i);refs=c['references'];refs[0]['locator']='ICALP 2022, article 100: Section 2 (proof systems, leaf-count size and configuration space), notation on p. 100:5, and Problem 5.1, pp. 100:16–100:17.'
refs.append(dict(id='journal2023',title='Space characterizations of complexity measures and size-space trade-offs in propositional proof systems',authors='Theodoros Papamakarios; Alexander Razborov',year=2023,url='https://doi.org/10.1016/j.jcss.2023.04.006',locator='Journal of Computer and System Sciences 137, pp. 20–36, November 2023. Publisher abstract and bibliographic record checked; the complete journal PDF was not accessible in this review. The detailed statement is checked against the complete conference paper.'))
save(i,dict(title='Does small proof space imply short tree-like resolution refutations?',formal='For μ equal to resolution clause space CSpace or PCR monomial space MSpace_K, does there exist a constant a≥1 and C>0 such that every unsatisfiable CNF F on n≥2 variables satisfies log₂(S_T(F)+1)≤C((μ(F)+1)log₂(n+1))^a? Determine the validity of this comparison in each of the two cases in the source’s Problem 5.1. For monomial space, K is an arbitrary fixed field and the constants may depend on K, but not on F or n. Here S_T is minimum tree-like resolution leaf count. The opposite comparison, bounding each space measure by logarithmic tree-like size up to these polynomial/logarithmic losses, is known.',definitions='A literal is xᵢ or its negation ¬xᵢ. A clause is a disjunction of literals and a CNF F is a finite conjunction of clauses over variables x₁,…,xₙ; unsatisfiable means no Boolean assignment satisfies every clause. Resolution derives C∨D from C∨xᵢ and D∨¬xᵢ, and allows weakening from C to C∨D; input clauses can be used as axioms. A refutation derives the empty clause. A tree-like proof uses each derived occurrence as a premise at most once, duplicating occurrences when necessary; S_T(F) is the minimum number of leaves, rather than total literal count. A configuration proof starts with no stored clauses and at each step downloads an input clause, erases a stored clause, or adds a resolvent/weakening of clauses currently stored; it ends with the empty clause stored. CSpace(F) is the minimum, over such proofs with unrestricted length, of the maximum number of simultaneously stored clauses. For PCR fix K and use the polynomial ring K[x₁,…,xₙ,y₁,…,yₙ], where yᵢ represents ¬xᵢ. A line P means P=0. Logical axioms are z²−z for each z among xᵢ,yᵢ and xᵢ+yᵢ−1. The encoding of a clause is the product of its false-literal indicators: xᵢ contributes yᵢ and ¬xᵢ contributes xᵢ. From P,Q derive αP+βQ for α,β∈K; from P derive zP for any literal variable z. A PCR refutation derives 1. Its configurations may download axioms, erase lines or add an inference whose premises are stored. The monomial space of a configuration is the number of distinct formal monomials with nonzero coefficients occurring anywhere in its stored polynomials, counted once across all lines; coefficients and exponents are not separately charged. MSpace_K(F) is the minimum maximum monomial space over all PCR refutations. Every proof is finite and minima concern the specified syntactic systems. The source’s relation A⪯B permits A(F)≤((B(F))log n)^{O(1)}; ≈ means both directions. The harmless +1 terms here cover one-leaf or other constant-size cases. No polynomial-length restriction is imposed on the space-minimizing proof.',question_type='yes_no',answer_criterion='For each stated space measure, prove the universal polynomial/logarithmic simulation bound or refute it by showing that no constants C,a work for all unsatisfiable formulas (with K fixed in the PCR case). The two variants must be reported separately. A polynomial separation between raw measures does not refute a comparison that explicitly permits arbitrary polynomial and logarithmic factors.',context_blocks=[b('Space permits reuse, while a proof tree duplicates work','A configuration refutation can retain a clause, use it many times and discard it later. A tree-like refutation must duplicate reused derivations. The question asks how much tree size can grow when only a small working memory is needed.','primary'),b('Regularized space already matches logarithmic tree size','The source proves equivalence when a proof’s space is multiplied by the logarithm of its length and then minimized over proofs. Removing that length penalty is precisely the missing step in this comparison; it is not the product of two separately minimized quantities.','primary'),b('The approximation relation is deliberately coarse','The symbol ≈ does not mean equality or equality up to constants. A gap by a fixed polynomial, or by a polylogarithmic factor in n, is allowed. This convention is essential for understanding what would constitute a separation.','primary'),b('The known example does not settle this scale','The source exhibits formulas with clause space four and quadratic tree-like size. Their logarithmic tree size is only O(log n), so that example does not violate the proposed comparison.','primary')],why='Would determine whether low working memory in propositional refutations fundamentally limits repeated work, clarifying strong size-space trade-offs and the cost of converting reusable proofs into trees.',references=refs,progress=[dict(date='2022',text='The source identifies a cluster containing logarithmic tree-like size and regularized clause/monomial space, and leaves ordinary space versus that cluster open in Problem 5.1.',citation='primary'),dict(date='2023',text='The journal publication’s abstract retains the same characterization and trade-off framework; no solution of the ordinary-space comparison is asserted there.',citation='journal2023')],status='source_open',status_note='Read the complete conference definitions and Problem 5.1, checked the later journal record/abstract, and searched subsequent work through 12 September 2026. No resolution of these exact coarse comparisons was located. The journal full text was inaccessible; current openness is therefore recorded as source-open rather than certified by a new theorem audit.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A structural relationship between proof memory, reuse and tree size, with direct consequences for strong proof size-space trade-offs. Existing score retained.',assessed_on=DATE),review_note='Expanded all abbreviations, specified the polynomial/logarithmic meaning of ≈, leaf-count size, unrestricted-length clause space and fixed-field PCR monomial space. Retained the source’s two variants and made their separate answer requirements explicit.',working_summary=dict(sentences=['The source compares working memory in refutations with the logarithm of minimum tree-like resolution size.','Its two memory measures are stored clauses in resolution and distinct monomials in polynomial calculus with resolution.','The comparison allows polynomial losses and powers of log n, so it is much coarser than a constant-factor identity.','A length-penalized version of space is already known to satisfy the comparison.','The unresolved issue is whether ordinary space can be substantially smaller on this scale.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal2023'])),notes=['Defined CSpace, fixed-field PCR MSpace and tree-like leaf-count size.','Expanded ≈ into quantified polynomial/logarithmic inequalities.','Distinguished ordinary from regularized space and retained both source variants.','Checked the later journal record and searched subsequent work.'],checked_sources=[r['url'] for r in refs]+['https://people.cs.uchicago.edu/~papamakarios/'])

i='TCS-2914';_,c=card(i);refs=c['references'];refs[0]['locator']='ITCS 2022, article 40: Definitions 10–11 (layered multi-output ROBPs), Section 4 (opposite-direction separation), and Section 7, p. 40:21 (requested direction).'
refs.append(dict(id='full',title='The Space Complexity of Sampling — revised full version',authors='Eshan Chattopadhyay; Jesse Goodman; David Zuckerman',year=2021,url='https://eccc.weizmann.ac.il/report/2021/106/',pdf_url='https://eccc.weizmann.ac.il/report/2021/106/revision/1/download',locator='Revision 1 of ECCC TR21-106, Section 7, paragraph “A separation between sampling with ROBPs and AC⁰ circuits”; retains the small-width question without a quantitative resource/error target.'))
issue='The source asks for a separation with “small width” but does not fix the ROBP width and random-input-length bounds, uniformity, or exact versus approximate sampling. In particular, “cannot be sampled” does not specify a total-variation error threshold or asymptotic error function. These are part of the target, not just presentation choices: an unrestricted-width ROBP can generate any finite dyadic distribution. A complete benchmark needs the intended efficient sampler class and approximation convention.'
save(i,dict(title='A distribution easy for read-once branching programs but hard for AC⁰ samplers',formal='Does there exist a family of distributions D_n on {0,1}^n that can be generated by small-width read-once branching programs in the source’s layered-output model, but cannot be generated by polynomial-size constant-depth Boolean circuits? The requested direction is ROBP-easy and AC⁰-hard. The source leaves the precise ROBP resource bounds and the sampling-error requirement unspecified, so this is not yet a fully quantified separation claim.',definitions='For a finite set Ω, a probability distribution assigns nonnegative masses summing to one. A sampler is a deterministic function of independent uniformly random input bits; its output distribution is the pushforward of the uniform distribution. The source’s multi-output ROBP has ℓ+1 layers, each with at most w states, one start state, and exactly two outgoing edges at each nonfinal state, labeled 0 and 1. At step i it reads the i-th fresh random bit and follows that edge. Each edge carries a finite output string; all edges between the same pair of layers have the same output length γᵢ, with Σᵢγᵢ=n. Output is the concatenation along the path, and cannot subsequently be reread or changed. The width w is memory capacity in states, corresponding to at most ⌈log₂w⌉ bits for the state. An AC⁰ sampler family consists of Boolean circuits with n designated outputs, AND/OR gates of unbounded fan-in and NOT gates, with a depth bound d independent of n and size at most C(n+1)^a for constants C,a. Each circuit receives independent fair random bits; random-input nodes are counted in its size so their number is polynomially bounded. Exact sampling means equality of distributions. Total-variation distance between D,E on {0,1}^n is (1/2)Σ_z|D(z)−E(z)|; approximate sampling requires this to be at most a specified tolerance. The source does not select a tolerance or quantitative w(n),ℓ(n), and does not require a uniform circuit/program construction.',answer_criterion='Specify the intended ROBP width/length and exact or approximate sampling convention, then prove or refute existence of a distribution family separated in this direction against every AC⁰ family. For a positive answer, the lower bound must exclude all such circuit samplers at the stated error, not merely circuits computing one chosen encoding of the sampler. The already known AC⁰-easy/ROBP-hard direction does not answer this question.',context_blocks=[b('Sampling does not require computing a chosen function','A distribution can have many different generators. A lower bound for computing a function on a supplied input therefore does not establish that its input-output distribution is hard to sample from fresh randomness.','primary'),b('The opposite direction is already separated','The paper shows that shallow circuits can sample distributions that require exponential ROBP width. One example is a uniformly random string followed by an identical copy, which stresses the sequential sampler’s memory. The new question reverses the roles.','primary'),b('The output schedule is part of the model','Every edge at a given layer emits the same number of bits. Allowing output positions or lengths to depend freely on the path is a different model discussed separately by the source.','primary'),b('The full version does not close the specification gap','The revised full paper retains the question and its reference to small width, but does not state a width exponent, seed-length limit or approximation threshold for the desired separation.','full'),b('Remaining formulation issue',issue)],why='Would distinguish the power of shallow parallel generation from sequential generation with limited memory, complementing the separation already known in the other direction.',references=refs,progress=[dict(date='2021–2022',text='The paper separates AC⁰-easy distributions from ROBP sampling and leaves the reverse direction open in both checked versions.',citation='primary')],status='source_open',status_note='Read the exact ROBP output conventions, the opposite-direction theorem and both future-directions paragraphs. Searches through 12 September 2026 found no result resolving the intended reverse separation. Quantitative resources and sampling error still require specification.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the separation direction and layered output model; retained resource/error ambiguities.']),importance=dict(score=c['importance']['score'],method='editorial',reason='A foundational comparison of parallel and memory-bounded generation, where decision-complexity intuitions do not determine sampling complexity. Existing score retained.',assessed_on=DATE),review_note='Removed extractor/disperser solution advice, restored the exact layered multi-output model and defined statistical error while recording that the source does not choose its required value.',working_summary=dict(sentences=['The goal is a distribution family generated easily by read-once branching programs but not by AC⁰ circuits.','The sequential sampler reads fresh random bits once and emits output in a fixed layer schedule.','The paper already proves a strong separation in the opposite direction.','Hardness of computing a chosen generator does not establish hardness of sampling its output law.','The intended small-width bound and exact-versus-approximate error convention remain unspecified.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full'])),notes=['Recovered the correct ROBP-easy/AC⁰-hard direction.','Defined layered multi-output branching programs and constant-depth circuit samplers.','Removed technique advice and distinguished function computation from distribution generation.','Checked the full revision and identified missing resource/error conventions.'],checked_sources=[r['url'] for r in refs],state='improved_unfinished')

i='TCS-2958';_,c=card(i);refs=c['references'];refs[0]['locator']='STACS 2022, article 44: Section 1.1 and Theorems 1–2; Section 4, pp. 44:11–44:12 (removing the bounded-output-coefficient restriction for equations of VP).'
refs.extend([dict(id='combined',title='On the Existence of Algebraic Natural Proofs — combined full version',authors='Prerona Chatterjee; Mrinal Kumar; C. Ramya; Ramprasad Saptharishi; Anamay Tengse',year=2025,url='https://arxiv.org/abs/2004.14147',pdf_url='https://arxiv.org/pdf/2004.14147v4',locator='Version 4, 3 February 2025: Definitions 1.2–1.3, Question 1.4, Theorem 1.6 (explicit polynomial-size quantifiers), and Section 1.4. Combines FOCS 2020 and STACS 2022 papers; retains the unrestricted-coefficient VP question.'),dict(id='journal2026',title='On the Existence of Algebraic Natural Proofs',authors='Prerona Chatterjee; Mrinal Kumar; C. Ramya; Ramprasad Saptharishi; Anamay Tengse',year=2026,url='https://doi.org/10.1007/s00037-026-00289-8',locator='computational complexity 35, article 7, published 7 August 2026. Publisher metadata and abstract checked; full journal PDF was unavailable. Detailed statements checked against the complete February 2025 author revision.')])
save(i,dict(title='Efficient equations for VP with unrestricted complex coefficients',formal='For every fixed integer c≥1, do there exist nonzero polynomials P_n in N_n=binom(n+n^c,n) coefficient variables, with degree and algebraic circuit size at most C_c N_n^{a_c}, such that for every fixed integer b≥1 there is n₀(c,b) for which P_n(coeff(f))=0 whenever n≥n₀(c,b) and f∈ℂ[x₁,…,xₙ] has total degree at most n^c and an algebraic circuit of size at most n^b? Constants C_c,a_c and the family (P_n) may depend on c, but not on b. Coefficients of f may be arbitrary complex numbers. This expresses the source’s eventual vanishing on every polynomial-size family, without demanding a common finite threshold across all circuit-size exponents.',definitions='An algebraic circuit over ℂ is a finite directed acyclic graph with inputs x₁,…,xₙ and arbitrary complex constants, binary addition and multiplication gates, and one output. Subtraction is allowed via multiplication by −1; there are no division gates. Its size is its number of vertices. It computes an exact formal polynomial, and each constant is one field element regardless of its bit description. VP_ℂ consists of polynomial families with polynomially bounded total degree and polynomially bounded nonuniform algebraic circuit size. For d=n^c, list all monomials x₁^{α₁}⋯xₙ^{αₙ} with αᵢ≥0 and Σᵢαᵢ≤d in a fixed lexicographic order of exponent vectors. There are N_n=binom(n+d,n) such monomials. coeff(f) is the full vector of their coefficients, including zeros. P_n is a polynomial over ℂ whose variables are these N_n coordinates. Nonzero means not the zero formal polynomial; over ℂ it is equivalent to being nonzero at some coefficient vector. Both degree and circuit size of P_n are bounded by a fixed polynomial in N_n, not in n. The equations themselves are nonuniform: there is no additional requirement to construct their circuits in polynomial time from n. Vanishing must hold for all circuits under each fixed polynomial size bound eventually; the threshold can depend on that bound. Restricting c,b to positive integers covers arbitrary fixed polynomial exponents by increasing them. The statement imposes no bound on output coefficients of f or on constants used inside its circuit, and requests no explicit hard polynomial on which P_n is nonzero.',question_type='yes_no',answer_criterion='Prove existence of such a nontrivial polynomial-degree, polynomial-circuit-size family for every c, or refute the universal existence statement for at least one c. Vanishing only on polynomials with bounded integer coefficients, or only on a fixed restricted circuit architecture, does not establish the claim. Nonexistence of equations for VNP alone does not refute existence for VP.',context_blocks=[b('An equation is a test on the whole coefficient vector','The input to P_n is the description of another polynomial by all its coefficients. An equation vanishes on easy polynomials and is nonzero somewhere else. Its efficiency is measured against this much larger coefficient-vector dimension.','combined'),b('The bounded-coefficient theorem concerns output polynomials','The known positive result restricts the final polynomial’s coefficients, for example to {−1,0,1}. Its computing circuit may still use arbitrary complex constants internally. Removing that semantic restriction is the question here.','combined'),b('The relevant existence notion is nonuniform','The source’s phrase “efficiently constructible equations” is formalized by membership in VP. The checked revision explicitly describes its upper-bound proofs as existential; the card therefore does not add a uniform circuit-generation algorithm.','combined'),b('The conditional VNP theorem leaves VP undecided','Under sufficiently strong permanent hardness, the source rules out efficient equations for VNP over characteristic-zero fields. Since VP is a smaller class, an equation vanishing on VP need not vanish on VNP, so the theorem does not answer this card.','primary'),b('The later combined work retains the distinction','The February 2025 full version explicitly keeps Question 1.4 open while generalizing its positive and conditional negative results. The work was published in August 2026; the checked publisher abstract does not claim a resolution of unrestricted-coefficient VP.','journal2026')],why='Would clarify whether a broad family of algebraic lower-bound certificates can recognize all efficiently computable polynomials once arbitrary coefficients are allowed.',references=refs,progress=[dict(date='2020–2022',text='Efficient equations are known for bounded-output-coefficient subclasses; the STACS paper gives a conditional obstruction for unrestricted-coefficient VNP while leaving VP open.',citation='primary'),dict(date='2025-02-03',text='The combined full revision states the unrestricted VP problem as Question 1.4 and distinguishes it from its expanded positive and conditional results.',citation='combined'),dict(date='2026-08-07',text='The combined work is published in computational complexity, volume 35, article 7.',citation='journal2026')],status='source_open',status_note='Checked the original question, complete February 2025 combined revision and August 2026 publisher record/abstract. No resolution of the unrestricted-complex-coefficient VP target was found through 12 September 2026. The full journal PDF was unavailable; the detailed current formulation is grounded in the checked author revision.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='Tests the reach of algebraic natural-proof certificates for general polynomial-size circuits, with coefficient freedom as the unresolved boundary. Existing score retained.',assessed_on=DATE),review_note='Recovered the coefficient-vector dimension, unrestricted complex output coefficients, nontriviality, degree and nonuniform circuit bounds. Made eventual quantifiers explicit using the revised paper’s size-bound convention, avoiding the impossible reading that all polynomial-size families share one finite-n cutoff.',working_summary=dict(sentences=['An equation for VP is a nonzero polynomial that eventually vanishes on coefficient vectors of all polynomial-size arithmetic computations.','Its own degree and circuit size should be polynomial in the coefficient-vector dimension.','The question removes the bounded-integer-coefficient restriction from known positive results.','Efficient equations here are nonuniform circuit families, without a separate construction-time requirement.','The checked combined revision and new journal publication retain the distinction between this VP question and conditional hardness for VNP.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','combined','journal2026'])),notes=['Recovered the exact coefficient-vector target and unrestricted complex field model.','Specified nontriviality, degree, circuit-size and nonuniformity conventions.','Made polynomial-size-family quantifiers explicit using the combined revision.','Checked the February 2025 full version and August 2026 publication, separating VP from VNP.'],checked_sources=[r['url'] for r in refs])
